import React, { useState, useRef } from 'react';
import { createPortal } from 'react-dom';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmLogo } from 'app/components/ui-kits/atoms/zimmLogo';
import { ZimmIcon } from 'app/components/ui-kits/atoms/zimmIcon';
import { ZimmNavItem } from 'app/components/ui-kits/atoms/zimmNavItem';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { ZimmTextInput } from 'app/components/ui-kits/atoms/zimmTextInput';
import { ZimmInputAction } from 'app/components/ui-kits/molecules/zimmInputAction';
import { isSafeHref } from 'app/utils/safeHref';
import { useSubscribeModal } from 'app/hooks/useSubscribeModal';
import { noop } from '@salesforce/retail-react-app/app/utils/utils';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useHistory } from 'react-router-dom';
import { HOME_HREF } from '@salesforce/retail-react-app/app/constants';
import type { FooterConfigEntry } from 'app/types/contentful';
import { FOOTER_FIXTURE } from './contentfulFixture';

// Named constant to avoid magic string comparison in the render tree
/** Non-breaking space. Marks a label whose line break is intentional — see the nav item below. */
const NBSP = '\u00A0';

/**
 * Theme recipe key. Namespaced rather than 'Footer' because extendTheme deep-merges — a recipe
 * named Footer would inherit base SFCC's Footer instead of replacing it. Must match the key
 * registered in theme/components/index.ts; a typo here silently yields an empty style object.
 */
const ZIMM_FOOTER_RECIPE = 'ZimmFooter';
// Locale control label. Hardcoded, and deliberately NOT fixture data — region and currency
// come from site config (config/default.js: defaultSite 'ZimmermannAU'), not Contentful, so
// FooterConfigEntry has no field for them. Set to match the site the app actually serves at
// '/'; it previously read "United States (USD) / ENG" on an AU storefront. The real fix reads
// site.l10n.defaultLocale and the site's currency via useMultiSite when the locale selector
// lands, at which point this constant goes away rather than getting a different literal.
const LOCALE_LABEL_PLACEHOLDER = 'Australia (AUD) / ENG';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
type FooterProps = {
  /** Contentful FooterConfigEntry. Pass FOOTER_FIXTURE from contentfulFixture.ts in stories/tests. */
  data: FooterConfigEntry;
  copyrightYear?: number;
  /** Forces SubscribeSection into its post-submit state. For Storybook/tests only. */
  initialSubscribed?: boolean;
  /**
   * Opt in to the HPC-035 first/last-name capture modal. Defaults to false: SFCC-55 ships the
   * Stay in Touch section as an input plus submit button only, and the modal has no design yet.
   */
  enableNameCapture?: boolean;
  /** Click handler for the wordmark. Mirrors the header's onLogoClick prop, defaulting to
   *  noop so the presentational Footer never navigates on its own. */
  onLogoClick?: () => void;
  /** href for the Privacy Policy link inside the subscribe modal (HPC-037). Locale-aware at runtime. */
  privacyPolicyHref?: string;
};

// ---------------------------------------------------------------------------
// All footer styling lives in theme/components/footer.ts and is consumed via
// useMultiStyleConfig('ZimmFooter') → __css. Nothing is styled at the call site.
// ---------------------------------------------------------------------------

// Subscribe heading ("Keep in Touch") — same type scale as navigation, distinct colour and lineHeight
// colour.ts note: text.inverseGrey and text.muted are both #969696 as of develop commit 6fa8e92
// lineHeight override: textStyles.navigation says 'normal' (≈14.4px at 12px font), but Figma
// wants 14px, so subscribeHeading sets lineHeight explicitly to --zimm-font-lineheight-2xs.
// These values now live in theme/components/footer.ts's subscribeHeading part, not here.
// ---------------------------------------------------------------------------
// Subscribe modal (HPC-035 + HPC-037)
// Rendered via createPortal so the overlay escapes the footer stacking context.
// ---------------------------------------------------------------------------
// HPC-037 copy — update when UX supplies final content
const PRIVACY_CONSENT_COPY = 'By providing your details, you agree to receive email updates from Zimmermann. View our';
const ACCESSIBILITY_DISCLAIMER_COPY =
  'Zimmermann is committed to providing accessible services. ' +
  'If you experience any difficulty, please contact us for assistance.';

type SubscribeModalProps = {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (firstName: string, lastName: string) => void;
  privacyPolicyHref: string;
};

const SubscribeModal = ({ isOpen, onClose, onSubmit, privacyPolicyHref }: SubscribeModalProps) => {
  const { mounted, formRef, firstFocusRef } = useSubscribeModal({ isOpen, onClose });
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  const handleFormSubmit = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const form = e.currentTarget;
    // namedItem returns Element | RadioNodeList | null. The cast keeps `| null` rather than
    // asserting it away — these fields are always single <input>s rendered by ZimmTextInput,
    // but a missing field must stay a null the `?.` below can actually catch. Same pattern as
    // zimmInputAction's handleSubmit.
    const firstName = (form.elements.namedItem('firstName') as HTMLInputElement | null)?.value ?? '';
    const lastName = (form.elements.namedItem('lastName') as HTMLInputElement | null)?.value ?? '';
    onSubmit(firstName.trim(), lastName.trim());
  };

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) onClose();
  };

  if (!mounted || !isOpen) return null;

  return createPortal(
    <chakra.div role="presentation" onClick={handleBackdropClick} __css={styles.modalOverlay}>
      <chakra.div
        role="dialog"
        aria-modal="true"
        aria-labelledby="zimm-subscribe-modal-title"
        aria-describedby="zimm-subscribe-modal-consent"
        __css={styles.subscribeModalPanel}
      >
        <form ref={formRef} onSubmit={handleFormSubmit} noValidate>
          {/* Title */}
          <chakra.h2 id="zimm-subscribe-modal-title" __css={styles.modalTitle}>
            Join Us
          </chakra.h2>

          {/* First Name */}
          <chakra.div ref={firstFocusRef} __css={styles.modalField}>
            <ZimmTextInput label="First Name" name="firstName" />
          </chakra.div>

          {/* Last Name */}
          <chakra.div __css={styles.modalFieldLast}>
            <ZimmTextInput label="Last Name" name="lastName" />
          </chakra.div>

          {/* Privacy consent copy (HPC-037) */}
          <chakra.p id="zimm-subscribe-modal-consent" __css={styles.modalConsent}>
            {PRIVACY_CONSENT_COPY}{' '}
            {/* Same guard as the contact channels: privacyPolicyHref is a prop, so a caller
                can supply anything. Unsafe or absent renders the label as plain text rather
                than an anchor that goes nowhere. */}
            {isSafeHref(privacyPolicyHref) ? (
              <chakra.a href={privacyPolicyHref} __css={styles.modalConsentLink}>
                Privacy Policy
              </chakra.a>
            ) : (
              <chakra.span __css={styles.modalConsentLink}>Privacy Policy</chakra.span>
            )}
            .
          </chakra.p>

          {/* Accessibility disclaimer (HPC-037) */}
          <chakra.p __css={styles.modalDisclaimer}>{ACCESSIBILITY_DISCLAIMER_COPY}</chakra.p>

          {/* Actions */}
          <chakra.div __css={styles.modalActions}>
            <ZimmButton variant="secondary" size="medium" label="Cancel" type="button" onClick={onClose} />
            <ZimmButton variant="primary" size="medium" label="Continue" type="submit" />
          </chakra.div>
        </form>
      </chakra.div>
    </chakra.div>,
    document.body,
  );
};

// ---------------------------------------------------------------------------
// Subscribe section
// ---------------------------------------------------------------------------
// 'unavailable' shown until HPC-036 (Omneo) lands; prevents false "You're on the list!" feedback.
// 'success'/'error' set only after a confirmed/failed Omneo response (post HPC-036).
type SubmitState = 'idle' | 'unavailable' | 'success' | 'error';

// The HPC-036 sign-up payload: footer email (HPC-034) + modal names (HPC-035).
// Assembled across two steps, POSTed to Omneo → Emarsys when the integration lands.
type PendingSignup = { email: string; firstName: string; lastName: string };

type SubscribeSectionProps = {
  heading: string;
  body: string;
  initialSubscribed?: boolean;
  privacyPolicyHref: string;
  enableNameCapture?: boolean;
};

const SUBSCRIBE_SUCCESS_MESSAGE = "You're on the list! Be the first to know about new collections and new arrivals.";
const SUBSCRIBE_UNAVAILABLE_MESSAGE = 'Subscription is temporarily unavailable. Please try again later.';

const SubscribeSection = ({
  heading,
  body,
  initialSubscribed = false,
  privacyPolicyHref,
  enableNameCapture = false,
}: SubscribeSectionProps) => {
  // Map the Storybook-only `initialSubscribed` flag to the success state.
  // Post HPC-036, 'success' will only be reached via a confirmed Omneo response.
  const [submitState, setSubmitState] = useState<SubmitState>(initialSubscribed ? 'success' : 'idle');
  // Ref, not state: nothing renders from it, so a re-render on capture would be wasted.
  // The footer input unmounts once submitState leaves 'idle', so the email must be
  // captured here at step 1 or it is unrecoverable at step 2.
  const pendingSignupRef = useRef<PendingSignup>({ email: '', firstName: '', lastName: '' });
  const [modalOpen, setModalOpen] = useState(false);
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  const handleEmailSubmit = (email: string) => {
    pendingSignupRef.current.email = email;
    if (enableNameCapture) {
      setModalOpen(true);
      return;
    }
    // Descoped path, and the default. SFCC-55's AC scopes this section to "an email input field
    // and submit button as a placeholder component" and defers the Omneo sign-up to a separate
    // story. The name-capture modal is HPC-035/HPC-037 (both confirmed in .docs/prd/homepage.md
    // §6) but has no Figma node — all nine of its theme parts are undesigned, unlike the 27
    // Figma-referenced parts around it. So it does not ship enabled: submitting a valid email
    // goes straight to the placeholder message. Flip this prop on once Kiera supplies the design
    // and HPC-035 is scheduled; the modal and its coverage are already built and tested.
    setSubmitState('unavailable');
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  const handleModalSubmit = (firstName: string, lastName: string) => {
    pendingSignupRef.current = { ...pendingSignupRef.current, firstName, lastName };
    // PLACEHOLDER until HPC-036 (Omneo integration) lands: POST pendingSignupRef.current here.
    // On confirmed response → setSubmitState('success'). On failure → setSubmitState('error').
    // 'unavailable' is shown until the integration is live; never show false success.
    setModalOpen(false);
    setSubmitState('unavailable');
    // Nothing was sent, so nothing needs retaining — the record holds customer PII and there
    // is no request for it to outlive. When HPC-036 adds the POST above, this reset stays; it
    // just moves to after a confirmed response. React memory only, never storage, never logged.
    pendingSignupRef.current = { email: '', firstName: '', lastName: '' };
  };

  return (
    <div>
      <chakra.p __css={styles.subscribeHeading}>{heading}</chakra.p>
      <chakra.p __css={styles.subscribeBody}>{body}</chakra.p>
      <chakra.div aria-live="polite" __css={styles.subscribeControl}>
        {submitState === 'idle' && (
          <ZimmInputAction
            label="Email"
            type="email"
            name="footer-email"
            icon="chevron-right"
            buttonLabel="Subscribe"
            inverse
            onSubmit={handleEmailSubmit}
          />
        )}
        {submitState === 'success' && <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_SUCCESS_MESSAGE}</chakra.p>}
        {(submitState === 'unavailable' || submitState === 'error') && (
          <chakra.p __css={styles.subscribeSuccess}>{SUBSCRIBE_UNAVAILABLE_MESSAGE}</chakra.p>
        )}
      </chakra.div>

      {enableNameCapture && (
        <SubscribeModal
          isOpen={modalOpen}
          onClose={() => setModalOpen(false)}
          onSubmit={handleModalSubmit}
          privacyPolicyHref={privacyPolicyHref}
        />
      )}
    </div>
  );
};

// ---------------------------------------------------------------------------
// Contact icon row — rendered below the link list in the Contact column
// ---------------------------------------------------------------------------
// Figma: Icon-list has pt-4px (alias/space/100) above it and 4px internal gap between icons.
// hrefs sourced from Contentful FooterConfigEntry (HPC-034). Until that integration lands,
// all hrefs are undefined and each icon renders as a non-interactive but labelled <span> —
// visible in the layout and announced by screen readers, but absent from the tab order.
// See the inline note on the fallback branch below for the full a11y reasoning.
// When a href arrives it switches to a live <a>, no other changes needed.
type ContactIconRowProps = {
  phoneHref?: string; // locale-aware tel: href from Contentful
  whatsAppHref?: string; // WhatsApp URL from Contentful
  emailHref?: string; // mailto: address from Contentful
};

type ContactLink = { href?: string; label: string; icon: 'phone' | 'whatsapp' | 'email' };

/**
 * True when following the href would navigate away from the storefront.
 *
 * Takes `string | undefined` rather than `string` so the caller does not need an `as string`
 * to satisfy it inside an isSafeHref branch. isSafeHref returns a plain boolean, which carries
 * no narrowing, and a `href is string` predicate would be unsound — an unsafe value like
 * `javascript:void(0)` is a string that returns false, so the else branch would narrow to
 * `undefined` incorrectly. An absent href never leaves the site, so `?? ''` is the honest answer.
 *
 * Derived from the scheme rather than keyed to a channel name: tel: and mailto: hand off to
 * the OS dialer or mail client and never navigate, so a target on them does nothing. An
 * http(s) channel — WhatsApp today — is a real cross-origin navigation and opens in a new
 * tab so a shopper mid-browse does not lose the site. Any future http(s) channel inherits
 * this without another edit here.
 */
const leavesTheSite = (href: string | undefined): boolean => /^https?:/i.test(href ?? '');

/** WCAG 3.2.5 — a link that opens a new tab has to say so in its accessible name. */
const NEW_TAB_SUFFIX = ' — opens in a new tab';

const ContactIconRow = ({ phoneHref, whatsAppHref, emailHref }: ContactIconRowProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
  const links: ContactLink[] = [
    { href: phoneHref, label: 'Call us', icon: 'phone' },
    { href: whatsAppHref, label: 'WhatsApp', icon: 'whatsapp' },
    { href: emailHref, label: 'Email us', icon: 'email' },
  ];
  return (
    <chakra.div __css={styles.contactRow}>
      {links.map(({ href, label, icon }) =>
        // isSafeHref, not a truthiness check: these arrive from Contentful, so a
        // javascript:/data:/protocol-relative value would otherwise be rendered
        // straight onto an anchor. Rejected values fall through to the span below,
        // which is already the correct treatment for "no usable destination".
        isSafeHref(href) ? (
          <chakra.a
            key={icon}
            href={href}
            // rel is explicit rather than relying on target="_blank" implying noopener:
            // that is browser default behaviour, not a guarantee, and noreferrer also
            // stops the storefront URL leaking to the third party.
            {...(leavesTheSite(href) ? { target: '_blank', rel: 'noopener noreferrer' } : {})}
            aria-label={leavesTheSite(href) ? `${label}${NEW_TAB_SUFFIX}` : label}
            __css={styles.contactIconLink}
          >
            <ZimmIcon type={icon} size="md" aria-hidden={true} />
          </chakra.a>
        ) : (
          // Fallback for a channel with no usable destination — either the field is absent
          // for this storefront, or isSafeHref rejected the value. Both reach here, and both
          // want the same treatment. NON-INTERACTIVE but PERCEIVABLE:
          //   - <span>: no href, no tabIndex, so nothing promises an action that cannot be
          //     performed (avoids the WCAG 2.4.4 / 3.2.4 false affordance).
          //   - labelled, not aria-hidden: ZimmIcon emits role="img" + aria-label, so screen
          //     reader users learn the channel exists instead of getting silence (avoids the
          //     1.1.1 information loss the previous aria-hidden caused).
          // Not dead code: contact channels are optional per storefront, so a locale that
          // supplies only e.g. email still renders the other two icons this way.
          <chakra.span key={icon} __css={styles.contactIconLink}>
            <ZimmIcon type={icon} size="md" aria-label={label} />
          </chakra.span>
        ),
      )}
    </chakra.div>
  );
};

// ---------------------------------------------------------------------------
// Bottom bar
// ---------------------------------------------------------------------------
type BottomBarProps = {
  copyrightYear: number;
  copyrightOwner: string;
  legalLinks: ReadonlyArray<{ label: string; href: string }>;
};

const BottomBar = ({ copyrightYear, copyrightOwner, legalLinks }: BottomBarProps) => {
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});
  return (
    <chakra.div __css={styles.bottomBar}>
      <chakra.div __css={styles.bottomInner}>
        <chakra.button
          type="button"
          aria-label="Change locale"
          __css={styles.localeButton}
          // PLACEHOLDER: wire to locale selector once available.
          // Label and destination are hardcoded until sourced from active locale/site config.
          onClick={undefined}
        >
          {/* localeText = Figma "footer-item": py-8px on text only, icon sits outside.
                        Typography and colour are inherited from the parent localeButton theme. */}
          <chakra.span __css={styles.localeText}>{LOCALE_LABEL_PLACEHOLDER}</chakra.span>
          <ZimmIcon type="chevron-right" size="sm" aria-hidden={true} />
        </chakra.button>

        <chakra.div __css={styles.bottomRight}>
          {/* Copyright is a direct flex child of bottomRight to match Figma's flat Legal row.
                        py-8px matches the legal link py used in ZimmNavItem style below. */}
          <chakra.span __css={styles.copyright}>
            Copyright &copy; {copyrightYear} {copyrightOwner}
          </chakra.span>
          <chakra.div __css={styles.legalGrid}>
            {legalLinks.map((link) => (
              <ZimmNavItem
                key={link.label}
                href={link.href}
                label={link.label}
                inverse
                // Figma Small/Default: py-[8px] — override base h-[24px] with height:auto + vertical padding
                // width is applied via legalGrid's '& > a' child selector in footer.ts
                sx={styles.legalLink}
              />
            ))}
          </chakra.div>
        </chakra.div>
      </chakra.div>
    </chakra.div>
  );
};

// ---------------------------------------------------------------------------
// Footer
// ---------------------------------------------------------------------------

/**
 * Zimmermann global footer — presentational. Receives its content as props and
 * fetches nothing, matching every other Contentful-backed component in the repo
 * (`DuplexSection`, `HeroBanner`, `ProductHero`, `VideoEmbed`).
 *
 * `data` is required by design: static content belongs in the story or in the
 * container below, never baked into the component that renders production UI.
 * Omneo email submit and Cookie Settings are separate stories (HPC-035, HPC-038).
 */
export const Footer = ({
  data,
  copyrightYear = new Date().getFullYear(),
  initialSubscribed = false,
  privacyPolicyHref = '#',
  onLogoClick = noop,
  enableNameCapture = false,
}: FooterProps) => {
  const {
    subscribeHeading,
    subscribeBody,
    navGroups,
    legalLinks = [],
    copyrightOwner,
    phoneHref,
    whatsAppHref,
    emailHref,
  } = data.fields;

  const legalItems = legalLinks.map((e) => ({ label: e.fields.label, href: e.fields.href }));
  const styles = useMultiStyleConfig(ZIMM_FOOTER_RECIPE, {});

  return (
    <chakra.footer role="contentinfo" __css={styles.container}>
      <chakra.div __css={styles.main}>
        <chakra.div __css={styles.contentRow}>
          <chakra.div __css={styles.subscribe}>
            <SubscribeSection
              heading={subscribeHeading ?? ''}
              body={subscribeBody ?? ''}
              initialSubscribed={initialSubscribed}
              privacyPolicyHref={privacyPolicyHref}
              enableNameCapture={enableNameCapture}
            />
          </chakra.div>

          <chakra.div __css={styles.links}>
            <chakra.div __css={styles.linksInner}>
              {navGroups.map((group) => (
                <chakra.div key={group.sys.id} __css={styles.linkCol}>
                  {/* Figma section column: flex-col gap-16px — the column gap replaces
                      marginBottom on the heading. Contact heading has a 4px left offset, which
                      is why it selects a different part rather than patching this one. */}
                  <chakra.p
                    __css={group.fields.showContactChannels ? styles.columnHeadingContact : styles.columnHeading}
                  >
                    {group.fields.heading}
                  </chakra.p>
                  {/* Figma Links div (2228:19423): flex-col, items-start, width 100%, gap 0.
                      DELIBERATE DEVIATION: Figma puts the Contact items at x=0 while indenting
                      only its heading 4px (wrapper 40000407:22289) — About and Help headings sit
                      flush at 0, so that asymmetry reads as a stray wrapper rather than intent.
                      We indent the Contact items to match their heading so the column aligns as a
                      unit. The icon row below needs no indent: its 24px box centres a 16px glyph,
                      so the glyph edge already lands at 4px. Pending Kiera. */}
                  <chakra.ul __css={styles.linkList}>
                    {group.fields.links.map((link) => (
                      <chakra.li
                        key={link.sys.id}
                        // Part selection, not composition: the three <li> treatments (plain,
                        // Contact-indented, hug-width) are defined in footer.ts. Hug wins over
                        // the indent because it is the rule that changes the layout — a label
                        // that needs both would need its own part, and none exists today.
                        // See footer.ts's linkListItemHug / linkListItemContact for the why.
                        __css={
                          link.fields.label.includes(NBSP)
                            ? styles.linkListItemHug
                            : group.fields.showContactChannels
                            ? styles.linkListItemContact
                            : styles.linkListItem
                        }
                      >
                        {/* Each item h-[24px] items-center, no gap. ZimmNavItem's baseStyle supplies
                            minHeight 24px, whiteSpace normal (so the label below can wrap) and uppercase. */}
                        <ZimmNavItem href={link.fields.href} label={link.fields.label} inverse />
                      </chakra.li>
                    ))}
                    {/* Contact channels are the LAST CHILD OF THE LIST, not a sibling of it —
                        Figma's Icon-list (40002081:14616) sits inside Links at y=72, directly
                        after "CONNECT WITH US" ends at y=72, so only its own 4px padding-top
                        separates them. Rendered outside the <ul> it instead picked up linkCol's
                        16px column gap and sat 20px low against Figma's 4px. */}
                    {group.fields.showContactChannels && (
                      <chakra.li __css={styles.linkListItem}>
                        <ContactIconRow phoneHref={phoneHref} whatsAppHref={whatsAppHref} emailHref={emailHref} />
                      </chakra.li>
                    )}
                  </chakra.ul>
                </chakra.div>
              ))}
            </chakra.div>
          </chakra.div>
        </chakra.div>

        <chakra.div __css={styles.logo}>
          {/* Button + programmatic nav, matching the header's wordmark rather than an <a href>.
              The handler comes from FooterContainer — see the note there on why it uses
              buildUrl + history.push rather than useNavigation. styles.logoButton is a chrome
              reset only, so the logo keeps its own geometry. */}
          <chakra.button type="button" aria-label="Zimmermann home" onClick={onLogoClick} __css={styles.logoButton}>
            <ZimmLogo variant="inverse" />
          </chakra.button>
        </chakra.div>
      </chakra.div>

      <BottomBar copyrightYear={copyrightYear} copyrightOwner={copyrightOwner ?? ''} legalLinks={legalItems} />
    </chakra.footer>
  );
};

// ---------------------------------------------------------------------------
// Container — the default export
// ---------------------------------------------------------------------------

/**
 * The component SFCC actually renders. Base `_app/index.jsx` resolves
 * `@salesforce/retail-react-app/app/components/footer` through the overrides system
 * and renders `<Footer />` with **no props**, so there is no upstream container to
 * own the data. This wrapper is that seam, and the only place static content lives.
 *
 * HPC-034: replace FOOTER_FIXTURE with the Contentful CDA fetch **here** — the
 * presentational Footer above does not change. Note that puts a fetch inside
 * `components/`, which components.md reserves for containers; if that matters,
 * HPC-034 should override `_app` instead (Tier 2 shared shell — coordinate first).
 */
const FooterContainer = (props: Omit<FooterProps, 'data'>) => {
  // buildUrl + history.push, not useNavigation. useNavigation special-cases the home path
  // (`path === '/' ? '/' : updatedHref`), so navigate('/') pushes a bare '/' and skips the
  // site/locale prefix — on a prefixed storefront that drops the shopper onto the default
  // site. This is the exact pair base _app's onLogoClick uses, so both wordmarks resolve
  // home the same way on every storefront.
  const { buildUrl } = useMultiSite();
  const history = useHistory();
  return <Footer data={FOOTER_FIXTURE} onLogoClick={() => history.push(buildUrl(HOME_HREF))} {...props} />;
};

export default FooterContainer;

