import React, { type CSSProperties } from 'react';
import { Button as ChakraButton, IconButton } from '@chakra-ui/react';
import { ZimmIcon } from '../zimmIcon';
import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';

// All hover/press/focus/disabled interaction states live in theme/components/button.ts.
// ZimmButton is a thin mapping layer: Zimmermann props (inverse, large/medium) → Chakra
// variant/size names that button.ts recognises.

type ZimmButtonBaseProps = {
  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
  label: string;
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  inverse?: boolean;
  onClick?: () => void;
  style?: CSSProperties;
};

type ZimmLabelButtonProps = ZimmButtonBaseProps & {
  variant?: 'primary' | 'secondary';
  size?: 'large' | 'medium';
  fullWidth?: boolean;
};

type ZimmIconButtonProps = ZimmButtonBaseProps & {
  variant: 'icon';
  icon: ZimmIconType;
  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
  size?: ZimmIconSize;
};

type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;

const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';

/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
 *  are handled by `theme/components/button.ts` — no React state for hover/press/focus. */
export const ZimmButton = (props: ZimmButtonProps) => {
  const { label, type = 'button', disabled = false, inverse = false, onClick, style } = props;

  if (props.variant === 'icon') {
    return (
      <IconButton
        aria-label={label}
        type={type}
        isDisabled={disabled}
        onClick={onClick}
        variant={inverse ? 'iconInverse' : 'icon'}
        size="icon"
        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
        style={style}
      />
    );
  }

  const variant = props.variant ?? 'primary';
  const size = props.size === 'medium' ? 'sm' : 'lg';
  // Maps inverse prop to the *Inverse variant suffix defined in button.ts.
  const chakraVariant = `${variant}${inverse ? 'Inverse' : ''}`;

  return (
    <ChakraButton
      type={type}
      isDisabled={disabled}
      onClick={onClick}
      variant={chakraVariant}
      size={size}
      width={props.fullWidth ? '100%' : undefined}
      style={style}
    >
      {label}
    </ChakraButton>
  );
};
