import React from 'react';
import { iconSizes } from 'app/theme/foundation';
import {
  ArrowDownIcon,
  ArrowLinkIcon,
  ArrowUpIcon,
  BagIcon,
  BagSelectedIcon,
  CalendarIcon,
  CarouselIcon,
  CarouselSelectedIcon,
