════════ hooks/useSubscribeModal.ts ════════
import { useCallback, useEffect, useRef, useState } from 'react';

const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';

type UseSubscribeModalParams = {
  /** Whether the dialog is currently open. */
  isOpen: boolean;
  /** Called when the dialog should close (Escape). */
  onClose: () => void;
};

type UseSubscribeModalReturn = {
  /** False until after the first client render, so the portal is not created during SSR. */
  mounted: boolean;
  /** Attach to the dialog's <form> — bounds the Tab trap. */
  formRef: React.RefObject<HTMLFormElement>;
  /** Attach to the wrapper around the first field — its <input> receives initial focus. */
  firstFocusRef: React.RefObject<HTMLDivElement>;
};

/**
 * Dialog mechanics for the footer's subscribe modal: mount gating, focus save/restore,
 * body-scroll lock, and the Escape/Tab keyboard trap.
 *
 * Extracted from SubscribeModal per components.md's extract-to-hook threshold — four effects,
 * three of them with cleanup functions. None of it touches JSX, so the component keeps only its
 * markup and the recipe lookup. Behaviour is unchanged; the effect order and dependency arrays
 * are preserved exactly, because focus restore depends on running after the open-effect's
 * cleanup.
 *
 * @param params isOpen and the close callback
 * @returns the mount flag plus the two refs the dialog markup has to attach
 */
export const useSubscribeModal = ({ isOpen, onClose }: UseSubscribeModalParams): UseSubscribeModalReturn => {
  const [mounted, setMounted] = useState(false);
  const formRef = useRef<HTMLFormElement>(null);
  const firstFocusRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<Element | null>(null);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Save the trigger element on open so focus can be restored on close
  useEffect(() => {
    if (isOpen) {
      triggerRef.current = document.activeElement;
      // Defer so the portal has rendered before we try to focus inside it
      const id = setTimeout(() => {
        const firstInput = firstFocusRef.current?.querySelector<HTMLElement>('input');
        firstInput?.focus();
      }, 0);
      return () => clearTimeout(id);
    } else {
      // Return focus to the element that opened the modal
      if (triggerRef.current instanceof HTMLElement) {
        triggerRef.current.focus();
      }
    }
  }, [isOpen]);

  // Lock body scroll while modal is open
  useEffect(() => {
    if (!isOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, [isOpen]);

  // Keyboard: Escape to close, Tab trap within modal
  const handleKeyDown = useCallback(
    (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
        return;
      }
      if (e.key !== 'Tab' || !formRef.current) return;

      const focusable = Array.from(formRef.current.querySelectorAll<HTMLElement>(FOCUSABLE)).filter(
        (el) => !el.hasAttribute('disabled'),
      );

      const first = focusable[0];
      const last = focusable[focusable.length - 1];

      if (e.shiftKey && document.activeElement === first) {
        e.preventDefault();
        last?.focus();
      } else if (!e.shiftKey && document.activeElement === last) {
        e.preventDefault();
        first?.focus();
      }
    },
    [onClose],
  );

  useEffect(() => {
    if (!isOpen) return;
    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, handleKeyDown]);

  return { mounted, formRef, firstFocusRef };
};
════════ hooks/useZimmTextInputState.ts ════════
import { useRef, useState } from 'react';
import type React from 'react';

type UseZimmTextInputStateParams = {
  onChange?: (value: string) => void;
  /** Controlled value. When provided the caller owns the value and internal state is unused. */
  value?: string;
  /** Seed for the uncontrolled case. Ignored when `value` is provided. */
  defaultValue?: string;
};

type UseZimmTextInputStateReturn = {
  value: string;
  focused: boolean;
  inputRef: React.RefObject<HTMLInputElement>;
  handleChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  handleClear: () => void;
  setFocused: React.Dispatch<React.SetStateAction<boolean>>;
};

/**
 * Manages the interaction state for ZimmTextInput that the theme cannot express: the value,
 * and focus. The floated-label decision is NOT made here — the label colour and the border
 * and label colour cascades live in `theme/components/zimmTextInput.ts`, which receives
 * `focused` and `filled` as recipe props. Hover is a CSS pseudo-class in that recipe, so it
 * costs no React state.
 *
 * Supports both modes, following the React convention: pass `value` to control it from a
 * parent (a form, or ZimmInputAction), or omit it and the hook owns the value internally,
 * seeded from `defaultValue`. `onChange` fires in both modes.
 * @returns value, focus flag, the input ref, and the event handlers
 */
export const useZimmTextInputState = ({
  onChange,
  value: controlledValue,
  defaultValue,
}: UseZimmTextInputStateParams): UseZimmTextInputStateReturn => {
  // Controlled when the caller passes `value`; otherwise the hook owns it, seeded from
  // `defaultValue`. Reading through this indirection is what makes the returned `value`
  // correct in both modes — and the recipe derives the floated-label state from it.
  const isControlled = controlledValue !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue ?? '');
  const value = isControlled ? controlledValue : internalValue;
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!isControlled) setInternalValue(e.target.value);
    onChange?.(e.target.value);
  };

  const handleClear = () => {
    if (!isControlled) setInternalValue('');
    onChange?.('');
    inputRef.current?.focus();
  };

  return { value, focused, inputRef, handleChange, handleClear, setFocused };
};
════════ utils/safeHref.ts ════════
/**
 * Allow-list guard for hrefs that originate outside the codebase.
 *
 * Anything reaching an `href` from Contentful, a URL parameter, or a prop supplied by a
 * caller we do not control has to pass through here first. `javascript:` and `data:` URLs
 * execute; a protocol-relative `//host` silently leaves the site. The `(?!\/)` lookahead is
 * what rejects the last case — it was a real bypass, closed in e9c2180.
 *
 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?!\/))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(href) : false);
════════ theme/fontFace.tsx ════════
import React from 'react';
import { Global, css } from '@emotion/react';
import { bundleBasePath, getEnvBasePath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';

/**
 * @font-face declarations for the self-hosted Futura Round faces.
 *
 * This is the only thing the font needs. `foundation/fonts.ts` already lists 'Futura Round'
 * as first preference in both FONT_REGULAR and FONT_MEDIUM, and every layer below it —
 * zimmTokens' --zimm-font-family-*, the 22 textStyles, every component recipe — already
 * resolves through that stack. Declaring the faces makes the name resolvable; nothing else in
 * the styling chain changes.
 *
 * Only two faces exist because only two are used: all 22 textStyles resolve to fontWeight 400
 * or 500, and fonts.body === fonts.heading, so there is no third stack to serve.
 *
 * Injected with a raw Emotion <Global> rather than Chakra's styles.global, for the same reason
 * zimmTokensGlobal.tsx documents: Chakra's style processor mangles quoted font-family values,
 * collapsing a stack like "'Futura Round', 'Century Gothic', sans-serif" to a single family.
 * Rendered in the app by _app-config/index.tsx AND in Storybook by .storybook/preview.tsx, so
 * type resolves identically in isolation and in the app — one shared definition so the two
 * mount points cannot drift.
 */

/**
 * Bundle-prefixed asset root, resolved synchronously.
 *
 * This deliberately reimplements the two lines of `getAssetUrl` rather than importing it.
 * That helper lives in `@salesforce/pwa-kit-react-sdk/ssr/universal/utils`, which also pulls
 * in `ssr-config` (cosmiconfig → fs) — fine on the server, but it would land in the browser
 * and Storybook bundles. Importing it lazily to dodge that is worse: this module's css`` is
 * evaluated at module-init, so an async import can never populate in time and every URL
 * silently loses its bundle prefix, 404s, and the browser falls back to the system font.
 *
 * `ssr-namespace-paths` is dependency-free, so it imports statically and resolves in one tick.
 *
 *   SSR      → `${getEnvBasePath()}${bundleBasePath}/${BUNDLE_ID}/`  e.g. /mobify/bundle/development/
 *   Browser  → window.Progressive.buildOrigin, set by the PWA Kit client runtime pre-hydration
 *   Storybook→ neither applies, so the bare /static path is used; .storybook/main.js maps
 *              overrides/app/static to /static via staticDirs, so it resolves there too.
 */
const assetRoot = (): string => {
  if (typeof window !== 'undefined') {
    // No type declarations ship for this SDK-injected global, so a narrow assertion is the
    // only option. Storybook has no Progressive global and falls through to '/'.
    const buildOrigin = (window as unknown as { Progressive?: { buildOrigin?: string } }).Progressive?.buildOrigin;
    return buildOrigin ?? '/';
  }
  return `${getEnvBasePath()}${bundleBasePath}/${process.env.BUNDLE_ID || 'development'}/`;
};

const fontUrl = (filename: string): string => `${assetRoot()}static/fonts/${filename}`;

const fontFaceCss = css`
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Regular.woff2')}') format('woff2');
    font-weight: 400;
    font-style: normal;
    font-display: swap;
  }
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Medium.woff2')}') format('woff2');
    font-weight: 500;
    font-style: normal;
    font-display: swap;
  }
`;

/** Declares the self-hosted Futura Round faces. Render once, high in the tree. */
export function ZimmFontFace(): React.ReactElement {
  return <Global styles={fontFaceCss} />;
}

