 * Allow-list rather than deny-list on purpose: a deny-list has to anticipate every scheme,
 * and browsers keep adding them.
 */
const SAFE_HREF_RE = /^(https?:|tel:|mailto:|#|\/(?!\/))/i;

/** True when `href` is safe to render on an anchor. Absent or unsafe values return false. */
export const isSafeHref = (href: string | undefined): boolean => (href ? SAFE_HREF_RE.test(href) : false);
════════ theme/fontFace.tsx ════════
import React from 'react';
import { Global, css } from '@emotion/react';
import { bundleBasePath, getEnvBasePath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';

/**
 * @font-face declarations for the self-hosted Futura Round faces.
 *
 * This is the only thing the font needs. `foundation/fonts.ts` already lists 'Futura Round'
 * as first preference in both FONT_REGULAR and FONT_MEDIUM, and every layer below it —
 * zimmTokens' --zimm-font-family-*, the 22 textStyles, every component recipe — already
 * resolves through that stack. Declaring the faces makes the name resolvable; nothing else in
 * the styling chain changes.
 *
 * Only two faces exist because only two are used: all 22 textStyles resolve to fontWeight 400
 * or 500, and fonts.body === fonts.heading, so there is no third stack to serve.
 *
 * Injected with a raw Emotion <Global> rather than Chakra's styles.global, for the same reason
 * zimmTokensGlobal.tsx documents: Chakra's style processor mangles quoted font-family values,
 * collapsing a stack like "'Futura Round', 'Century Gothic', sans-serif" to a single family.
 * Rendered in the app by _app-config/index.tsx AND in Storybook by .storybook/preview.tsx, so
 * type resolves identically in isolation and in the app — one shared definition so the two
 * mount points cannot drift.
 */

/**
 * Bundle-prefixed asset root, resolved synchronously.
 *
 * This deliberately reimplements the two lines of `getAssetUrl` rather than importing it.
 * That helper lives in `@salesforce/pwa-kit-react-sdk/ssr/universal/utils`, which also pulls
 * in `ssr-config` (cosmiconfig → fs) — fine on the server, but it would land in the browser
 * and Storybook bundles. Importing it lazily to dodge that is worse: this module's css`` is
 * evaluated at module-init, so an async import can never populate in time and every URL
 * silently loses its bundle prefix, 404s, and the browser falls back to the system font.
 *
 * `ssr-namespace-paths` is dependency-free, so it imports statically and resolves in one tick.
 *
 *   SSR      → `${getEnvBasePath()}${bundleBasePath}/${BUNDLE_ID}/`  e.g. /mobify/bundle/development/
 *   Browser  → window.Progressive.buildOrigin, set by the PWA Kit client runtime pre-hydration
 *   Storybook→ neither applies, so the bare /static path is used; .storybook/main.js maps
 *              overrides/app/static to /static via staticDirs, so it resolves there too.
 */
const assetRoot = (): string => {
  if (typeof window !== 'undefined') {
    // No type declarations ship for this SDK-injected global, so a narrow assertion is the
    // only option. Storybook has no Progressive global and falls through to '/'.
    const buildOrigin = (window as unknown as { Progressive?: { buildOrigin?: string } }).Progressive?.buildOrigin;
    return buildOrigin ?? '/';
  }
  return `${getEnvBasePath()}${bundleBasePath}/${process.env.BUNDLE_ID || 'development'}/`;
};

const fontUrl = (filename: string): string => `${assetRoot()}static/fonts/${filename}`;

const fontFaceCss = css`
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Regular.woff2')}') format('woff2');
    font-weight: 400;
    font-style: normal;
    font-display: swap;
  }
  @font-face {
    font-family: 'Futura Round';
    src: url('${fontUrl('FuturaRound-Medium.woff2')}') format('woff2');
    font-weight: 500;
    font-style: normal;
    font-display: swap;
  }
`;

/** Declares the self-hosted Futura Round faces. Render once, high in the tree. */
export function ZimmFontFace(): React.ReactElement {
  return <Global styles={fontFaceCss} />;
}

